mapper.select:
SELECT u.id, u.username, u.real_name, u.dept_id, u.phone, u.email, u.status, u.last_login_time, u.create_time, d.dept_name FROM sys_user u LEFT JOIN sys_dept d ON u.dept_id = d.id
AND u.username LIKE CONCAT('%', #{username}, '%')
AND u.real_name LIKE CONCAT('%', #{realName}, '%')
AND u.dept_id = #{deptId}
AND u.status = #{status}
ORDER BY u.create_time DESC
